const show = (make) => {
  try {
    make();
    console.log("ok");
  } catch (error) {
    console.log(error.name);
  }
};

show(() => new WeakRef([1, 2]));
show(() => new WeakRef(Symbol("tag")));
show(() => new WeakRef(Symbol.for("tag")));
show(() => new WeakRef(null));
show(() => new WeakRef(() => {}));
